1	import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
2	const here=path.dirname(fileURLToPath(import.meta.url)),[label,candidateArg,countArg]=process.argv.slice(2),root=path.resolve(candidateArg),main=JSON.parse(fs.readFileSync(path.join(here,'project.json'))).project,sha=b=>crypto.createHash('sha256').update(b).digest('hex'),rel=path.relative(here,root);assert(/^[a-z][a-z0-9-]*$/.test(label??''));assert(!rel.startsWith('..')&&!path.isAbsolute(rel));assert.notEqual(root,main);const bytes=fs.readFileSync(path.join(root,'.writer/state.json')),state=JSON.parse(bytes);assert.equal(state.units.length,Number(countArg));const inventory={};function walk(ref){const p=path.join(root,ref);if(!fs.existsSync(p))return;const st=fs.lstatSync(p);assert(!st.isSymbolicLink());if(st.isDirectory())for(const n of fs.readdirSync(p).sort())walk(ref+'/'+n);else{const b=fs.readFileSync(p);inventory[ref]={bytes:b.length,sha256:sha(b)};}}
3	for(const ref of ['正文','分段','大纲','人物','研究','审查','规则','.writer/drafts','.writer/sources'])walk(ref);for(const unit of state.units){assert.equal(sha(fs.readFileSync(path.join(root,unit.draft))),unit.sha256);for(const ref of Object.keys(unit.source_hashes??{}))if(!inventory[ref]&&fs.existsSync(path.join(root,ref)))walk(ref);}
4	const mainBytes=fs.readFileSync(path.join(main,'.writer/state.json')),result={ok:true,at:new Date().toISOString(),project:root,main,revision:state.revision,registered_units:state.units.length,state_sha256:sha(bytes),main_revision:JSON.parse(mainBytes).revision,main_state_sha256:sha(mainBytes),files:inventory};fs.writeFileSync(path.join(here,'checkpoint-'+label+'.json'),JSON.stringify(result,null,2)+'\n',{flag:'wx'});fs.writeFileSync(path.join(here,'checkpoint-'+label+'-state.json'),bytes,{flag:'wx'});fs.writeFileSync(path.join(here,'checkpoint-'+label+'-main-state.json'),mainBytes,{flag:'wx'});console.log(JSON.stringify({ok:true,label,units:state.units.length,files:Object.keys(inventory).length,main_revision:result.main_revision}));
